import{_ as s,o as e,c as n,am as t}from"./chunks/framework._FJXuPhs.js";const h=JSON.parse('{"title":"测试代码覆盖率","description":"","frontmatter":{"title":"测试代码覆盖率","excerpt":"摘要","date":"2025-08-29 00:53:04","updated":"2025-08-29 00:53:04"},"headers":[],"relativePath":"工程化/项目代码规范使用/测试代码覆盖率/index.md","filePath":"工程化/项目代码规范使用/测试代码覆盖率/index.md","lastUpdated":null}'),p={name:"工程化/项目代码规范使用/测试代码覆盖率/index.md"};function l(i,a,c,o,r,d){return e(),n("div",null,[...a[0]||(a[0]=[t(`<h3 id="mock-框架的使用" tabindex="-1">Mock 框架的使用 <a class="header-anchor" href="#mock-框架的使用" aria-label="Permalink to &quot;Mock 框架的使用&quot;">​</a></h3><p>项目使用的框架是 SpringBoot3 + Jacoco + Maven 的这种方式</p><ul><li><a href="/java-site/框架/工具类框架/Mock 框架的使用.html">框架 Mock</a></li></ul><h3 id="静态代码覆盖" tabindex="-1">静态代码覆盖 <a class="header-anchor" href="#静态代码覆盖" aria-label="Permalink to &quot;静态代码覆盖&quot;">​</a></h3><p>要求是：增量代码100%覆盖，生成对应的单元测试方法</p><ul><li>1、实践中最快的方式还是直接让对方读取 jacoco 的文件，然后让 cc 生成对应的代码 <ul><li>这里可以找一下工具获取到增量代码没有覆盖到文件（有类似工具的，实际工作的时候使用的是架构提供的工具）</li><li>如果不行的话，再手动微调，或者生成脚本辅助</li></ul></li><li>2、注意一下隔离</li><li>3、脚本文件 <ul><li>现在基本上不太使用了</li><li><a href="/java-site/工程化/项目代码规范使用/测试代码覆盖率/单元测试代码覆盖率-脚本文件.html">单元测试代码覆盖率-脚本文件</a></li><li><a href="/java-site/工程化/项目代码规范使用/测试代码覆盖率/脚本文件 v2.html">单元测试代码覆盖率-脚本文件 v2</a></li></ul></li></ul><p>pom 配置修改（隔离操作）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>            &lt;plugin&gt;  </span></span>
<span class="line"><span>                &lt;groupId&gt;org.apache.maven.plugins&lt;/groupId&gt;  </span></span>
<span class="line"><span>                &lt;artifactId&gt;maven-surefire-plugin&lt;/artifactId&gt;  </span></span>
<span class="line"><span>                &lt;version&gt;3.1.2&lt;/version&gt;  </span></span>
<span class="line"><span>                &lt;configuration&gt;                    &lt;groups&gt;serviceTest&lt;/groups&gt;  </span></span>
<span class="line"><span>                    &lt;forkCount&gt;2&lt;/forkCount&gt;          &lt;!-- 2个并行JVM --&gt;  </span></span>
<span class="line"><span>                    &lt;reuseForks&gt;false&lt;/reuseForks&gt;    &lt;!-- 不复用,确保隔离 --&gt;  </span></span>
<span class="line"><span>                    &lt;parallel&gt;classes&lt;/parallel&gt;       &lt;!-- 类级别并行 --&gt;  </span></span>
<span class="line"><span>&lt;!--                    &lt;includes&gt;--&gt;  </span></span>
<span class="line"><span>&lt;!--                        &lt;include&gt;**/DeductionSlipAppServiceTest.java&lt;/include&gt;--&gt;  </span></span>
<span class="line"><span>&lt;!--                    &lt;/includes&gt;--&gt;  </span></span>
<span class="line"><span>                &lt;/configuration&gt;  </span></span>
<span class="line"><span>            &lt;/plugin&gt;</span></span></code></pre></div><hr><p>目前就是直接使用 claude code 自动生成</p><p>类似这种脚本，然后看一下 jacococ 覆盖率文件</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mvn test -pl soms-service-start -Dtest=PickGoodsSelfProductAppServiceTest,PickGoodsSelfProductDomainServiceNewTest -Dmaven.test.failure.ignore=true jacoco:report</span></span></code></pre></div><p>也可以让大模型生成一个检测增量代码的覆盖率报告生成脚本</p><h3 id="单测运行" tabindex="-1">单测运行 <a class="header-anchor" href="#单测运行" aria-label="Permalink to &quot;单测运行&quot;">​</a></h3><p>命令</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/Library/Java/apache-maven-3.9.7/bin/mvn clean test -Dmaven.test.failure.ignore=true -Dpmd.skip=true -Drat.skip=true -Dcheckstyle.skip=true</span></span></code></pre></div><p>执行完之后会生成一下 jacoco 的覆盖率文件，然后拿这个文件进行对比，保证分支覆盖率是完全的</p><h3 id="踩坑记录" tabindex="-1">踩坑记录 <a class="header-anchor" href="#踩坑记录" aria-label="Permalink to &quot;踩坑记录&quot;">​</a></h3><p>如果出现断言或者验证失败的情况，直接 mvn test 是不行的，需要加一下命令</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mvn test -Dmaven.test.failure.ignore=true</span></span></code></pre></div><h4 id="多模块测试执行" tabindex="-1">多模块测试执行 <a class="header-anchor" href="#多模块测试执行" aria-label="Permalink to &quot;多模块测试执行&quot;">​</a></h4><p>典型的 Maven 多模块测试执行</p><p>问题说明</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>当你使用 -pl soms-service-start -am 时，Maven 会构建 soms-service-start 及其所有依赖模块（包括 soms-service-common）。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  关键问题：-Dtest=ProductDiagnosisServiceTest 参数会传递给所有模块，包括依赖模块。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  执行流程：</span></span>
<span class="line"><span>  1. Maven 构建 soms-service-common 模块</span></span>
<span class="line"><span>  2. Surefire 插件在 soms-service-common 中查找 ProductDiagnosisServiceTest</span></span>
<span class="line"><span>  3. 找不到该测试类 → 构建失败 ❌</span></span></code></pre></div><p>推荐其中一种解决方案： 忽略未找到测试的错误</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mvn test -pl soms-service-start -am \\</span></span>
<span class="line"><span>	-Dtest=SelfActivityProductAppServiceHandleMrsConflictTest \\</span></span>
<span class="line"><span>	-Dsurefire.failIfNoSpecifiedTests=false \\</span></span>
<span class="line"><span>	-Dlog.console=true \\</span></span>
<span class="line"><span>	-Dshein-cipher.kdms.unit-test=true</span></span></code></pre></div><p>让 claude code 先识别一下需要覆盖的文件，然后找到文件中没有覆盖的代码，生成对应的单元测试</p><p>编译修复，通过上述方式修复一下。（执行单个类，扫描一下其中ERROR的部分，不允许有异常和失败用例）</p><h4 id="cc-使用了-java25-编译-实际上环境是-17" tabindex="-1">cc 使用了 java25 编译，实际上环境是 17 <a class="header-anchor" href="#cc-使用了-java25-编译-实际上环境是-17" aria-label="Permalink to &quot;cc 使用了 java25 编译，实际上环境是 17&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  我这边的情况：</span></span>
<span class="line"><span>  - 运行 java -version → 显示 Java 17</span></span>
<span class="line"><span>  - 运行 mvn -version → 显示 Java 25（Maven 编译时用的）</span></span></code></pre></div><p>直接运行命令</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mvn -version</span></span></code></pre></div><p>可以看我们IDEA实际编辑使用的环境</p><p>遇到这种问题，可以让 cc 复查一下。</p>`,34)])])}const g=s(p,[["render",l]]);export{h as __pageData,g as default};
